children:
  @import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@500;600;700;800&family=Source+Serif+4:opsz,wght@8..60,500;8..60,600&display=swap');
#kbc-energy-widget{
      --ink:#161321;
      --ink-soft:#4f5668;
      --night:#0e0618;
      --night-2:#1a0a2a;
      --purple:#3b146d;
      --purple-2:#5e2aa5;
      --violet:#8d5be7;
      --gold:#d7a72a;
      --gold-2:#f4d574;
      --cream:#fff9e9;
      --lav:#f6f1fd;
      --lav-2:#ebe0fb;
      --green:#0d6a5a;
      --blue:#195c93;
      --line:rgba(59,20,109,.14);
      --white:#fff;
      --shadow:0 26px 80px rgba(31,15,55,.13);
      --shadow-sm:0 12px 36px rgba(31,15,55,.08);
      --radius:28px;
      --radius-sm:18px;
      --wrap:min(1200px,calc(100% - 40px));
    }
    #kbc-energy-widget, #kbc-energy-widget *{box-sizing:border-box}
    #kbc-energy-widget{scroll-behavior:smooth;scroll-padding-top:24px}
    #kbc-energy-widget{margin:0;background:#fff;color:var(--ink);font-family:Inter,Arial,Helvetica,sans-serif;line-height:1.65;-webkit-font-smoothing:antialiased;overflow-x:clip}
    #kbc-energy-widget img,#kbc-energy-widget video,#kbc-energy-widget svg{display:block;max-width:100%}
    #kbc-energy-widget a{color:inherit}
    #kbc-energy-widget button{font:inherit}
    #kbc-energy-widget .wrap{width:var(--wrap);margin-inline:auto}
    #kbc-energy-widget .sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}

    /* General */
    #kbc-energy-widget section{padding:clamp(68px,7vw,106px) 0}
    #kbc-energy-widget .section-head{max-width:850px;margin-bottom:2.1rem}
    #kbc-energy-widget .section-head.center{text-align:center;margin-inline:auto;margin-bottom:2.8rem}
    #kbc-energy-widget .kicker{display:inline-flex;align-items:center;gap:.55rem;color:var(--purple-2);font-size:.72rem;font-weight:800;letter-spacing:.13em;text-transform:uppercase;margin-bottom:.8rem}
    #kbc-energy-widget .kicker:before{content:"";width:27px;height:3px;border-radius:999px;background:linear-gradient(90deg,var(--gold),var(--violet))}
    #kbc-energy-widget h1,#kbc-energy-widget h2,#kbc-energy-widget h3,#kbc-energy-widget h4{font-family:Inter,Arial,Helvetica,sans-serif;text-wrap:balance}
    #kbc-energy-widget h2{margin:0 0 1rem;color:var(--night);font-size:clamp(2rem,4vw,3.55rem);line-height:1.06;letter-spacing:-.045em}
    #kbc-energy-widget .section-intro{margin:0;color:var(--ink-soft);font-size:clamp(1rem,1.4vw,1.12rem);line-height:1.72}
    #kbc-energy-widget .btn{min-height:50px;display:inline-flex;align-items:center;justify-content:center;gap:.55rem;border:1px solid transparent;border-radius:999px;padding:.82rem 1.15rem;text-decoration:none;font-weight:800;font-size:.88rem;transition:transform .2s ease,box-shadow .2s ease,background .2s ease}
    #kbc-energy-widget .btn:hover,#kbc-energy-widget .btn:focus-visible{transform:translateY(-2px);box-shadow:0 15px 32px rgba(0,0,0,.16)}
    #kbc-energy-widget .btn-primary{background:linear-gradient(135deg,var(--gold-2),var(--gold));color:#24132a}
    #kbc-energy-widget .btn-dark{background:linear-gradient(135deg,var(--purple),var(--purple-2));color:#fff}
    #kbc-energy-widget .btn-ghost{border-color:rgba(255,255,255,.28);background:rgba(255,255,255,.08);color:#fff}
    #kbc-energy-widget .reveal{opacity:0;transform:translateY(20px);transition:opacity .65s ease,transform .65s ease}
    #kbc-energy-widget .reveal.in{opacity:1;transform:none}

    /* Hero */
    #kbc-energy-widget .hero{position:relative;isolation:isolate;overflow:hidden;color:#fff;background:
      radial-gradient(circle at 12% 12%,rgba(142,85,231,.35),transparent 29%),
      radial-gradient(circle at 92% 15%,rgba(215,167,42,.15),transparent 26%),
      linear-gradient(135deg,#0b0414 0%,#281047 48%,#11071e 100%);padding:clamp(62px,7vw,108px) 0 0}
    #kbc-energy-widget .hero:before{content:"";position:absolute;z-index:-1;right:-220px;top:-250px;width:690px;height:690px;border-radius:50%;border:1px solid rgba(255,255,255,.08);box-shadow:0 0 0 70px rgba(255,255,255,.022),0 0 0 140px rgba(255,255,255,.014)}
    #kbc-energy-widget .hero:after{content:"";position:absolute;z-index:-1;left:-190px;bottom:40px;width:420px;height:420px;border-radius:50%;background:radial-gradient(circle,rgba(215,167,42,.1),transparent 67%)}
    #kbc-energy-widget .hero-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:clamp(2.2rem,5vw,5.4rem);align-items:center}
    #kbc-energy-widget .hero-eyebrow{display:inline-flex;align-items:center;gap:.55rem;padding:.48rem .78rem;border:1px solid rgba(255,255,255,.18);border-radius:999px;background:rgba(255,255,255,.07);font-size:.72rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--gold-2);margin-bottom:1.15rem}
    #kbc-energy-widget .hero-eyebrow:before{content:"";width:8px;height:8px;border-radius:50%;background:var(--gold-2);box-shadow:0 0 0 5px rgba(244,213,116,.12)}
    #kbc-energy-widget .hero h1{margin:0 0 1.25rem;max-width:760px;font-size:64px!important;line-height:.95;letter-spacing:-.045em;font-weight:800;color:#fff!important;-webkit-text-fill-color:#fff}
    #kbc-energy-widget .hero-title-line{display:block;color:#fff!important;-webkit-text-fill-color:#fff!important}
    #kbc-energy-widget .hero-title-word{display:inline-block}
    #kbc-energy-widget .hero-title-clarity{color:var(--gold)!important;-webkit-text-fill-color:var(--gold)!important;text-shadow:0 0 30px rgba(215,167,42,.2)}
    #kbc-energy-widget .hero-title-control{color:var(--white)!important;-webkit-text-fill-color:var(--white)!important;text-shadow:none}
    #kbc-energy-widget .hero-title-confidence{color:var(--gold)!important;-webkit-text-fill-color:var(--gold)!important;text-shadow:0 0 30px rgba(215,167,42,.2)}
    #kbc-energy-widget .hero-lead{max-width:710px;margin:0 0 1.5rem;color:#e9e1f2;font-size:clamp(1.04rem,1.7vw,1.28rem)}
    #kbc-energy-widget .hero-proof{display:flex;flex-wrap:wrap;gap:.55rem;margin-bottom:1.65rem}
    #kbc-energy-widget .hero-proof span{display:inline-flex;align-items:center;gap:.42rem;padding:.44rem .7rem;border-radius:999px;border:1px solid rgba(255,255,255,.13);background:rgba(255,255,255,.07);color:#f3edf8;font-size:.79rem;font-weight:700}
    #kbc-energy-widget .hero-proof svg{width:15px;height:15px;color:var(--gold-2)}
    #kbc-energy-widget .hero-actions{display:flex;flex-wrap:wrap;gap:.8rem}
    #kbc-energy-widget .hero-image-card{position:relative;justify-self:end;width:min(100%,520px);padding:10px;border-radius:32px;border:1px solid rgba(255,255,255,.17);background:linear-gradient(145deg,rgba(255,255,255,.21),rgba(255,255,255,.045));box-shadow:0 36px 100px rgba(0,0,0,.38)}
    #kbc-energy-widget .hero-image-stage{position:relative;overflow:hidden;border-radius:24px;aspect-ratio:16/10;background:#171022}
    #kbc-energy-widget .hero-image-stage>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center;transition:transform .6s ease}
    #kbc-energy-widget .hero-image-card:hover .hero-image-stage>img{transform:scale(1.035)}
    #kbc-energy-widget .hero-image-stage:after{content:"";position:absolute;inset:36% 0 0;background:linear-gradient(transparent,rgba(10,4,18,.92));pointer-events:none}
    #kbc-energy-widget .hero-image-badge{position:absolute;z-index:3;top:24px;left:24px;display:inline-flex;align-items:center;gap:.45rem;padding:.46rem .65rem;border-radius:999px;background:rgba(12,5,23,.72);backdrop-filter:blur(10px);border:1px solid rgba(255,255,255,.18);font-size:.69rem;font-weight:800}
    #kbc-energy-widget .hero-image-badge:before{content:"";width:7px;height:7px;border-radius:50%;background:var(--gold-2);box-shadow:0 0 0 4px rgba(244,213,116,.12)}
    #kbc-energy-widget .hero-image-caption{position:absolute;z-index:3;left:24px;right:24px;bottom:24px}
    #kbc-energy-widget .hero-image-caption strong{display:block;font:800 1.15rem/1.25 Inter,Arial,Helvetica,sans-serif;margin-bottom:.3rem}
    #kbc-energy-widget .hero-image-caption span{color:#ddd4e8;font-size:.78rem;line-height:1.48}
    #kbc-energy-widget .hero-statbar{margin-top:clamp(40px,6vw,72px);display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid rgba(255,255,255,.12)}
    #kbc-energy-widget .hero-stat{padding:1.3rem 1.2rem 1.55rem;border-right:1px solid rgba(255,255,255,.12)}
    #kbc-energy-widget .hero-stat:last-child{border-right:0}
    #kbc-energy-widget .hero-stat b{display:block;color:#fff;font:800 1.02rem/1.2 Inter,Arial,Helvetica,sans-serif;margin-bottom:.28rem}
    #kbc-energy-widget .hero-stat span{display:block;color:#cfc4da;font-size:.75rem;line-height:1.45}

    /* Capability rail */
    #kbc-energy-widget .capability-rail{padding:1rem 0;background:#fff;overflow:hidden}
    #kbc-energy-widget .rail-window{width:min(calc(100% - 28px),1200px);margin:0 auto;overflow:hidden;border:1px solid var(--line);border-radius:16px;background:#fff;box-shadow:var(--shadow-sm)}
    #kbc-energy-widget .rail-track{display:flex;width:max-content;animation:railMove 30s linear infinite}
    #kbc-energy-widget .rail-group{display:flex;align-items:center;gap:2.8rem;padding-right:2.8rem}
    #kbc-energy-widget .rail-item{display:flex;align-items:center;gap:.7rem;color:#30293b;font-size:.8rem;font-weight:800;white-space:nowrap}
    @keyframes railMove{to{transform:translateX(-50%)}}
    #kbc-energy-widget .capability-rail:hover .rail-track{animation-play-state:paused}

    /* Challenge / bento */
    #kbc-energy-widget .challenge{background:linear-gradient(180deg,#fff,#faf8fd)}
    #kbc-energy-widget .challenge-bento{display:grid;grid-template-columns:1.1fr .9fr;gap:1rem}
    #kbc-energy-widget .challenge-main{position:relative;overflow:hidden;min-height:390px;padding:2rem;border-radius:var(--radius);background:linear-gradient(135deg,rgba(24,8,43,.96),rgba(84,32,142,.76)),url('data:image/png;base64,') center 42%/cover no-repeat;color:#fff;box-shadow:var(--shadow)}
    #kbc-energy-widget .challenge-main:after{content:"";position:absolute;right:-90px;bottom:-120px;width:320px;height:320px;border-radius:50%;border:1px solid rgba(255,255,255,.17);box-shadow:0 0 0 55px rgba(255,255,255,.035),0 0 0 110px rgba(255,255,255,.022)}
    #kbc-energy-widget .challenge-main .kicker{color:var(--gold-2)}
    #kbc-energy-widget .challenge-main h3{position:relative;z-index:1;margin:0 0 1rem;max-width:640px;font-size:clamp(2rem,3.7vw,3.35rem);line-height:1.07;letter-spacing:-.04em}
    #kbc-energy-widget .challenge-main p{position:relative;z-index:1;max-width:650px;margin:0;color:#e7dcf1}
    #kbc-energy-widget .challenge-quote{position:absolute;z-index:1;left:2rem;right:2rem;bottom:2rem;padding-top:1rem;border-top:1px solid rgba(255,255,255,.2);font:700 1rem/1.55 Inter,Arial,Helvetica,sans-serif;color:var(--gold-2)}
    #kbc-energy-widget .challenge-side{display:grid;grid-template-columns:1fr 1fr;gap:1rem}
    #kbc-energy-widget .challenge-card{padding:1.35rem;border:1px solid var(--line);border-radius:22px;background:#fff;box-shadow:var(--shadow-sm)}
    #kbc-energy-widget .challenge-card .number{width:38px;height:38px;border-radius:13px;background:var(--cream);color:#765308;display:grid;place-items:center;font-weight:800;margin-bottom:.85rem}
    #kbc-energy-widget .challenge-card h3{font-size:1.04rem;margin:0 0 .45rem;color:var(--night)}
    #kbc-energy-widget .challenge-card p{margin:0;color:#667080;font-size:.82rem}

    /* Sector tabs */
    #kbc-energy-widget .sector-section{position:relative;overflow:hidden;background:linear-gradient(135deg,#0e0618,#281048 65%,#160824);color:#fff}
    #kbc-energy-widget .sector-section:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 8% 10%,rgba(141,91,231,.22),transparent 26%),radial-gradient(circle at 92% 90%,rgba(215,167,42,.12),transparent 28%)}
    #kbc-energy-widget .sector-section .wrap{position:relative;z-index:1}
    #kbc-energy-widget .sector-section h2{color:#fff}
    #kbc-energy-widget .sector-section .section-intro{color:#ded4e8}
    #kbc-energy-widget .sector-tabs{display:flex;gap:.65rem;flex-wrap:wrap;margin-bottom:1rem}
    #kbc-energy-widget .sector-tab{cursor:pointer;border:1px solid rgba(255,255,255,.16);background:rgba(255,255,255,.07);color:#fff;border-radius:999px;padding:.75rem 1rem;font-weight:800;font-size:.82rem}
    #kbc-energy-widget .sector-tab.active{background:var(--gold-2);color:#28162e;border-color:transparent}
    #kbc-energy-widget .sector-display{display:grid;grid-template-columns:.9fr 1.1fr;gap:1rem}
    #kbc-energy-widget .sector-copy,#kbc-energy-widget .sector-grid{border:1px solid rgba(255,255,255,.13);border-radius:24px;background:rgba(255,255,255,.065);backdrop-filter:blur(10px)}
    #kbc-energy-widget .sector-copy{padding:1.75rem;display:flex;flex-direction:column;justify-content:space-between;min-height:330px}
    #kbc-energy-widget .sector-copy h3{margin:0 0 .75rem;color:#fff;font-size:clamp(1.6rem,2.7vw,2.35rem);line-height:1.1}
    #kbc-energy-widget .sector-copy p{margin:0;color:#ddd4e7}
    #kbc-energy-widget .sector-cta{margin-top:1.4rem;display:inline-flex;align-items:center;gap:.45rem;color:var(--gold-2);font-weight:800;font-size:.82rem;text-decoration:none}
    #kbc-energy-widget .sector-grid{padding:1rem;display:grid;grid-template-columns:1fr 1fr;gap:.8rem}
    #kbc-energy-widget .sector-outcome{padding:1.15rem;border-radius:18px;background:rgba(255,255,255,.075);border:1px solid rgba(255,255,255,.1)}
    #kbc-energy-widget .sector-outcome strong{display:block;color:var(--gold-2);font-size:.9rem;margin-bottom:.32rem}
    #kbc-energy-widget .sector-outcome span{display:block;color:#d9cfe3;font-size:.76rem;line-height:1.48}
    #kbc-energy-widget .sector-photo-grid{display:grid;grid-template-columns:1.15fr .85fr .85fr;gap:1rem;margin-top:1rem}
    #kbc-energy-widget .sector-photo-card{position:relative;isolation:isolate;overflow:hidden;min-height:260px;margin:0;border-radius:24px;border:1px solid rgba(255,255,255,.14);background:#170a25;box-shadow:0 22px 60px rgba(0,0,0,.22)}
    #kbc-energy-widget .sector-photo-card img{width:100%;height:100%;min-height:260px;object-fit:cover;transition:transform .55s ease,filter .55s ease}
    #kbc-energy-widget .sector-photo-card:after{content:"";position:absolute;z-index:1;inset:0;background:linear-gradient(180deg,rgba(12,5,22,.04) 25%,rgba(12,5,22,.9) 100%);pointer-events:none}
    #kbc-energy-widget .sector-photo-card:hover img{transform:scale(1.04);filter:saturate(1.06)}
    #kbc-energy-widget .sector-photo-card figcaption{position:absolute;z-index:2;left:1.2rem;right:1.2rem;bottom:1.15rem;color:#fff}
    #kbc-energy-widget .sector-photo-card figcaption span{display:block;margin-bottom:.3rem;color:var(--gold-2);font-size:.67rem;font-weight:800;letter-spacing:.11em;text-transform:uppercase}
    #kbc-energy-widget .sector-photo-card figcaption strong{display:block;color:#fff;font:800 clamp(1rem,1.7vw,1.3rem)/1.25 Inter,Arial,Helvetica,sans-serif}

    /* Pathways */
    #kbc-energy-widget .pathways{background:#fff}
    #kbc-energy-widget .path-grid{display:grid;grid-template-columns:repeat(12,1fr);gap:1rem}
    #kbc-energy-widget .path-card{position:relative;overflow:hidden;min-height:310px;padding:1.45rem;border-radius:24px;border:1px solid var(--line);background:#fff;box-shadow:var(--shadow-sm);display:flex;flex-direction:column}
    #kbc-energy-widget .path-card:nth-child(1),#kbc-energy-widget .path-card:nth-child(4){grid-column:span 6}
    #kbc-energy-widget .path-card:nth-child(2),#kbc-energy-widget .path-card:nth-child(3){grid-column:span 3}
    #kbc-energy-widget .path-card:before{content:"";position:absolute;left:0;right:0;top:0;height:5px;background:linear-gradient(90deg,var(--purple-2),var(--gold))}
    #kbc-energy-widget .path-card.dark{background:linear-gradient(145deg,#160827,#3d146d);color:#fff;border-color:rgba(255,255,255,.08)}
    #kbc-energy-widget .path-index{display:flex;align-items:center;justify-content:space-between;margin-bottom:1.35rem}
    #kbc-energy-widget .path-index span:first-child{font-size:.69rem;font-weight:800;letter-spacing:.11em;text-transform:uppercase;color:var(--purple-2)}
    #kbc-energy-widget .dark .path-index span:first-child{color:var(--gold-2)}
    #kbc-energy-widget .path-icon{width:42px;height:42px;border-radius:14px;background:var(--lav);color:var(--purple);display:grid;place-items:center}
    #kbc-energy-widget .dark .path-icon{background:rgba(255,255,255,.1);color:var(--gold-2)}
    #kbc-energy-widget .path-card h3{margin:0 0 .72rem;color:var(--night);font-size:1.25rem;line-height:1.24}
    #kbc-energy-widget .dark h3{color:#fff}
    #kbc-energy-widget .path-card p{margin:0 0 1rem;color:#646d7d;font-size:.84rem}
    #kbc-energy-widget .dark p{color:#d9cfe4}
    #kbc-energy-widget .path-list{list-style:none;padding:0;margin:auto 0 0;display:grid;gap:.48rem}
    #kbc-energy-widget .path-list li{position:relative;padding-left:1.1rem;color:#4d5768;font-size:.78rem}
    #kbc-energy-widget .dark .path-list li{color:#e2d8eb}
    #kbc-energy-widget .path-list li:before{content:"";position:absolute;left:0;top:.63em;width:6px;height:6px;border-radius:50%;background:var(--gold)}

    /* What learners build */
    #kbc-energy-widget .outputs{background:linear-gradient(180deg,#faf8fd,#fff)}
    #kbc-energy-widget .output-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}
    #kbc-energy-widget .output-card{padding:1.3rem;border-radius:21px;border:1px solid var(--line);background:#fff;box-shadow:var(--shadow-sm)}
    #kbc-energy-widget .output-icon{width:43px;height:43px;border-radius:14px;background:linear-gradient(135deg,var(--lav),#fff4d7);color:var(--purple);display:grid;place-items:center;margin-bottom:.9rem}
    #kbc-energy-widget .output-card h3{margin:0 0 .45rem;color:var(--night);font-size:1rem}
    #kbc-energy-widget .output-card p{margin:0;color:#667080;font-size:.8rem}

    /* Career map */
    #kbc-energy-widget .career-section{background:#fff}
    #kbc-energy-widget .career-map{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}
    #kbc-energy-widget .career-card{position:relative;padding:1.4rem;border-radius:22px;border:1px solid var(--line);background:linear-gradient(180deg,#fff,#fcfaff);box-shadow:var(--shadow-sm)}
    #kbc-energy-widget .career-meta{display:flex;justify-content:space-between;align-items:center;gap:.8rem;margin-bottom:.9rem}
    #kbc-energy-widget .career-code{width:44px;height:44px;border-radius:14px;background:var(--purple);color:#fff;display:grid;place-items:center;font-size:.72rem;font-weight:800}
    #kbc-energy-widget .career-level{font-size:.67rem;font-weight:800;color:#72550b;background:var(--cream);padding:.3rem .55rem;border-radius:999px}
    #kbc-energy-widget .career-card h3{margin:0 0 .45rem;font-size:1.05rem;color:var(--night)}
    #kbc-energy-widget .career-card p{margin:0;color:#657080;font-size:.8rem}
    #kbc-energy-widget .career-arrow{display:flex;align-items:center;justify-content:center;margin:1.3rem 0 0;color:var(--purple-2);font-size:.78rem;font-weight:800}

    /* Delivery */
    #kbc-energy-widget .delivery{background:linear-gradient(135deg,#f7f2fc,#fff9ec)}
    #kbc-energy-widget .delivery-steps{display:grid;grid-template-columns:repeat(4,1fr);gap:1rem}
    #kbc-energy-widget .delivery-step{position:relative;padding:1.3rem;border-radius:21px;background:#fff;border:1px solid var(--line);box-shadow:var(--shadow-sm)}
    #kbc-energy-widget .delivery-step:not(:last-child):after{content:"";position:absolute;right:-.55rem;top:50%;width:1.1rem;height:2px;background:var(--gold)}
    #kbc-energy-widget .delivery-step small{display:block;color:var(--purple-2);font-size:.68rem;font-weight:800;letter-spacing:.11em;text-transform:uppercase;margin-bottom:.6rem}
    #kbc-energy-widget .delivery-step h3{margin:0 0 .45rem;color:var(--night);font-size:1.05rem}
    #kbc-energy-widget .delivery-step p{margin:0;color:#657080;font-size:.8rem}
    #kbc-energy-widget .delivery-visual{display:grid;grid-template-columns:1.05fr .95fr;align-items:stretch;overflow:hidden;margin:0 0 1rem;border:1px solid var(--line);border-radius:var(--radius);background:#fff;box-shadow:var(--shadow-sm)}
    #kbc-energy-widget .delivery-visual img{width:100%;height:100%;min-height:310px;object-fit:cover}
    #kbc-energy-widget .delivery-visual figcaption{display:flex;flex-direction:column;justify-content:center;padding:clamp(1.5rem,4vw,3rem)}
    #kbc-energy-widget .delivery-visual h3{margin:0 0 .7rem;color:var(--night);font-size:clamp(1.55rem,2.7vw,2.35rem);line-height:1.12;letter-spacing:-.035em}
    #kbc-energy-widget .delivery-visual p{margin:0;color:var(--ink-soft);font-size:.94rem}

    /* Testimonials: two cards on desktop, one card per carousel page on mobile. */
    #kbc-energy-widget .testimonials{position:relative;overflow:hidden;background:#fff;color:var(--ink)}
    #kbc-energy-widget .testimonials .wrap{position:relative}
    #kbc-energy-widget .testimonials h2{color:var(--night)}
    #kbc-energy-widget .testimonials .section-intro{color:var(--ink-soft)}
    #kbc-energy-widget .testimonial-note{display:inline-flex;align-items:center;gap:.45rem;margin-top:.85rem;color:#747b89;font-size:.7rem}
