    #kbc-energy-widget .testimonial-item{flex:0 0 50%;padding:2px .5rem}
    #kbc-energy-widget .quote-card{display:flex;min-height:330px;height:100%;padding:1.55rem;flex-direction:column;border:1px solid var(--line);border-left:4px solid var(--gold);border-radius:16px;background:var(--lav);box-shadow:var(--shadow-sm)}
    #kbc-energy-widget .quote-mark{height:38px;color:var(--purple-2);font:800 2.8rem/1 Inter,Arial,Helvetica,sans-serif}
    #kbc-energy-widget .quote-card blockquote{margin:.8rem 0 1.3rem;color:var(--ink);font-size:.95rem;line-height:1.72}
    #kbc-energy-widget .quote-meta{display:flex;align-items:center;gap:.8rem;margin-top:auto;padding-top:1rem;border-top:1px solid rgba(87,58,125,.13)}
    #kbc-energy-widget .avatar{display:grid;width:46px;height:46px;flex:0 0 auto;place-items:center;border-radius:50%;background:var(--purple-2);color:#fff;font-weight:800}
    #kbc-energy-widget .quote-meta strong{display:block;color:var(--night);font-size:.84rem}
    #kbc-energy-widget .quote-meta span{display:block;margin-top:.16rem;color:var(--ink-soft);font-size:.72rem}
    #kbc-energy-widget .testimonial-controls{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-top:1.1rem}
    #kbc-energy-widget .dots{display:flex;gap:.45rem}
    #kbc-energy-widget .dot{width:8px;height:8px;padding:0;border:0;border-radius:999px;background:rgba(92,37,156,.2);cursor:pointer;transition:width .2s,background .2s}
    #kbc-energy-widget .dot.active{width:28px;background:var(--purple-2)}
    #kbc-energy-widget .testimonial-arrows{display:flex;gap:.55rem}
    #kbc-energy-widget .arrow-btn{display:grid;width:44px;height:44px;padding:0;place-items:center;border:1px solid rgba(87,58,125,.18);border-radius:11px;background:#fff;color:var(--purple-2);cursor:pointer}
    #kbc-energy-widget .arrow-btn:hover{border-color:rgba(92,37,156,.2);background:var(--lav);color:var(--purple-2)}
    @media(max-width:700px){
      #kbc-energy-widget .testimonial-item{flex-basis:100%;padding-inline:2px}
      #kbc-energy-widget .quote-card{min-height:350px}
    }

    /* Employer impact */
    #kbc-energy-widget .employer{background:#fff}
    #kbc-energy-widget .impact-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:1rem}
    #kbc-energy-widget .impact-main{padding:1.7rem;border-radius:var(--radius);background:linear-gradient(145deg,#f7f2fc,#fff);border:1px solid var(--line);box-shadow:var(--shadow-sm)}
    #kbc-energy-widget .impact-main h3{margin:0 0 1rem;font-size:1.55rem;color:var(--night)}
    #kbc-energy-widget .impact-measures{display:grid;grid-template-columns:1fr 1fr;gap:.8rem}
    #kbc-energy-widget .impact-measure{padding:1rem;border-radius:17px;background:#fff;border:1px solid var(--line)}
    #kbc-energy-widget .impact-measure b{display:block;color:var(--purple);font-size:.87rem;margin-bottom:.25rem}
    #kbc-energy-widget .impact-measure span{display:block;color:#657080;font-size:.73rem}
    #kbc-energy-widget .impact-side{display:grid;gap:1rem}
    #kbc-energy-widget .impact-card{padding:1.3rem;border-radius:22px;color:#fff;background:linear-gradient(145deg,var(--purple),#682cb0);box-shadow:var(--shadow-sm)}
    #kbc-energy-widget .impact-card.gold{color:#26152d;background:linear-gradient(145deg,var(--gold-2),#e8b839)}
    #kbc-energy-widget .impact-card h3{margin:0 0 .45rem;font-size:1.05rem}
    #kbc-energy-widget .impact-card p{margin:0;color:#e4d9ed;font-size:.8rem}
    #kbc-energy-widget .impact-card.gold p{color:#503c12}

    /* Guide */
    #kbc-energy-widget .guide{background:linear-gradient(180deg,#faf8fd,#fff)}
    #kbc-energy-widget .guide-grid{display:grid;grid-template-columns:.72fr 1.28fr;gap:2rem;align-items:center}
    #kbc-energy-widget .guide-cover{max-width:390px;border-radius:28px;overflow:hidden;border:1px solid var(--line);box-shadow:var(--shadow)}
    #kbc-energy-widget .guide-list{display:grid;grid-template-columns:1fr 1fr;gap:.75rem;margin:1.25rem 0 1.5rem}
    #kbc-energy-widget .guide-list div{display:flex;align-items:flex-start;gap:.55rem;padding:.9rem;border-radius:16px;background:#fff;border:1px solid var(--line);color:#43394f;font-size:.79rem;font-weight:700}
    #kbc-energy-widget .guide-list div:before{content:"✓";width:20px;height:20px;flex:0 0 auto;border-radius:50%;display:grid;place-items:center;background:var(--cream);color:#765307;font-size:.68rem;font-weight:800}

    /* FAQ + CTA */
    #kbc-energy-widget .faq{background:#fff}
    #kbc-energy-widget #eligibility>.wrap{
      display:flex!important;
      width:calc(100% - 40px)!important;
      max-width:1000px!important;
      margin:0 auto!important;
      padding:0!important;
      flex-direction:column!important;
      align-items:center!important;
    }
    #kbc-energy-widget .faq .faq-heading{
      display:block!important;
      width:100%!important;
      max-width:850px!important;
      margin:0 auto 2.8rem!important;
      align-self:center!important;
      text-align:center!important;
    }
    #kbc-energy-widget .faq .faq-heading .kicker{
      justify-content:center!important;
    }
    #kbc-energy-widget .faq .faq-heading h2{
      width:100%!important;
      margin-right:auto!important;
      margin-left:auto!important;
      text-align:center!important;
    }
    #kbc-energy-widget .faq-list{
      display:grid;
      width:100%!important;
      max-width:940px!important;
      gap:.75rem;
      margin:0 auto!important;
      align-self:center!important;
    }
    #kbc-energy-widget details{border:1px solid var(--line);border-radius:18px;background:#fff;box-shadow:0 8px 24px rgba(31,15,55,.045);padding:0 1rem}
    #kbc-energy-widget summary{position:relative;list-style:none;cursor:pointer;padding:1rem 2.4rem 1rem 0;font:800 .92rem/1.45 Inter,Arial,Helvetica,sans-serif;color:var(--night)}
    #kbc-energy-widget summary::-webkit-details-marker{display:none}
    #kbc-energy-widget summary:after{content:"+";position:absolute;right:0;top:50%;transform:translateY(-50%);width:31px;height:31px;border-radius:50%;display:grid;place-items:center;background:var(--lav);color:var(--purple);font-size:1.1rem}
    #kbc-energy-widget details[open] summary:after{content:"−"}
    #kbc-energy-widget details p{margin:0 0 1rem;color:#657080;font-size:.82rem}
    #kbc-energy-widget .final-cta{position:relative;overflow:hidden;text-align:center;color:#fff;background:radial-gradient(circle at 10% 20%,rgba(215,167,42,.16),transparent 25%),linear-gradient(135deg,#0d0517,#3e146b 66%,#160824)}
    #kbc-energy-widget .final-cta:after{content:"";position:absolute;right:-150px;bottom:-200px;width:500px;height:500px;border-radius:50%;border:1px solid rgba(255,255,255,.08);box-shadow:0 0 0 65px rgba(255,255,255,.02)}
    #kbc-energy-widget .final-cta .wrap{position:relative;z-index:1}
    #kbc-energy-widget .final-cta h2{color:#fff;max-width:880px;margin-inline:auto}
    #kbc-energy-widget .final-cta p{max-width:730px;margin:0 auto 1.6rem;color:#e4dbee}
    #kbc-energy-widget .final-actions{display:flex;justify-content:center;flex-wrap:wrap;gap:.8rem}

    /* Keep titles legible over dark and image-based backgrounds in WordPress. */
    #kbc-energy-widget .hero h1,
    #kbc-energy-widget .challenge-main h3,
    #kbc-energy-widget .sector-section h2,
    #kbc-energy-widget .sector-section h3,
    #kbc-energy-widget .path-card.dark h3,
    #kbc-energy-widget .impact-card:not(.gold) h3,
    #kbc-energy-widget .final-cta h2,
    #kbc-energy-widget .hero-image-caption strong{
      color:#fff!important;
      -webkit-text-fill-color:#fff;
      background:none!important;
    }
    #kbc-energy-widget .hero-title-clarity{color:var(--gold)!important;-webkit-text-fill-color:var(--gold)!important}
    #kbc-energy-widget .hero-title-control{color:var(--white)!important;-webkit-text-fill-color:var(--white)!important}
    #kbc-energy-widget .hero-title-confidence{color:var(--gold)!important;-webkit-text-fill-color:var(--gold)!important}
    #kbc-energy-widget :is(a,button,summary):focus-visible{outline:3px solid var(--gold-2);outline-offset:3px}

    @media(max-width:1050px){
      #kbc-energy-widget .hero-grid,#kbc-energy-widget .challenge-bento,#kbc-energy-widget .sector-display,#kbc-energy-widget .impact-grid,#kbc-energy-widget .guide-grid,#kbc-energy-widget .delivery-visual{grid-template-columns:1fr}
      #kbc-energy-widget .hero-image-card{justify-self:center}
      #kbc-energy-widget .challenge-main{min-height:360px}
      #kbc-energy-widget .path-card:nth-child(1),#kbc-energy-widget .path-card:nth-child(4){grid-column:span 12}
      #kbc-energy-widget .path-card:nth-child(2),#kbc-energy-widget .path-card:nth-child(3){grid-column:span 6}
      #kbc-energy-widget .output-grid,#kbc-energy-widget .career-map{grid-template-columns:repeat(2,1fr)}
      #kbc-energy-widget .delivery-steps{grid-template-columns:repeat(2,1fr)}
      #kbc-energy-widget .delivery-step:nth-child(2):after{display:none}
      #kbc-energy-widget .sector-photo-grid{grid-template-columns:1fr 1fr}
      #kbc-energy-widget .sector-photo-card:first-child{grid-column:1/-1}
      #kbc-energy-widget .delivery-visual img{max-height:440px}
    }
    @media(max-width:700px){
      #kbc-energy-widget{--wrap:min(100% - 24px,1200px)}
      #kbc-energy-widget .hero{padding-top:52px}#kbc-energy-widget .hero h1{font-size:clamp(40px,11vw,54px)!important;line-height:.98}
      #kbc-energy-widget .hero-actions .btn{width:100%}
      #kbc-energy-widget .hero-image-card{width:min(100%,410px)}
      #kbc-energy-widget .hero-statbar{grid-template-columns:1fr 1fr}#kbc-energy-widget .hero-stat:nth-child(2){border-right:0}#kbc-energy-widget .hero-stat:nth-child(-n+2){border-bottom:1px solid rgba(255,255,255,.12)}
      #kbc-energy-widget .challenge-side,#kbc-energy-widget .sector-grid,#kbc-energy-widget .sector-photo-grid,#kbc-energy-widget .output-grid,#kbc-energy-widget .career-map,#kbc-energy-widget .delivery-steps,#kbc-energy-widget .impact-measures,#kbc-energy-widget .guide-list{grid-template-columns:1fr}
      #kbc-energy-widget .sector-photo-card:first-child{grid-column:auto}
      #kbc-energy-widget .sector-photo-card,#kbc-energy-widget .sector-photo-card img{min-height:230px}
      #kbc-energy-widget .delivery-visual img{min-height:240px}
      #kbc-energy-widget .challenge-main{min-height:430px;padding:1.4rem}#kbc-energy-widget .challenge-quote{left:1.4rem;right:1.4rem;bottom:1.4rem}
      #kbc-energy-widget .path-card:nth-child(n){grid-column:span 12;min-height:auto}
      #kbc-energy-widget .delivery-step:not(:last-child):after{display:none}
    }
    @media(prefers-reduced-motion:reduce){#kbc-energy-widget{scroll-behavior:auto}#kbc-energy-widget .rail-track{animation:none}#kbc-energy-widget .reveal{opacity:1;transform:none;transition:none}}

    /* Kent Business College design-system refinement */
    #kbc-energy-widget{
      --ink:#292f3d;
      --ink-soft:#626a7a;
      --night:#201432;
      --night-2:#2b1b43;
      --deep-purple:#2b1b43;
      --medium-purple:#3d285d;
      --muted-purple:#573a7d;
      --primary-purple:#5c259c;
      --bright-purple:#7540dc;
      --light-purple:#f1eafa;
      --section-bg:#f7f5fa;
      --soft-gold:#f5e8bf;
      --purple:#3d285d;
      --purple-2:#5c259c;
      --violet:#7540dc;
      --gold:#e5bd59;
      --gold-2:#e5bd59;
      --cream:#f1eafa;
      --lav:#f1eafa;
      --lav-2:#e7dcf4;
      --line:rgba(87,58,125,.13);
      --white:#ffffff;
      --shadow:0 8px 24px rgba(32,20,50,.055);
      --shadow-sm:0 8px 24px rgba(32,20,50,.055);
      --radius:18px;
      --radius-sm:16px;
      --wrap:min(1220px,calc(100% - 48px));
      background:#ffffff;
      color:var(--ink);
      font-family:Inter,Arial,Helvetica,sans-serif;
      font-size:16px;
      line-height:1.65;
      scroll-padding-top:24px;
    }
    #kbc-energy-widget *,
    #kbc-energy-widget *::before,
    #kbc-energy-widget *::after{
      font-family:Inter,Arial,Helvetica,sans-serif!important;
    }
    #kbc-energy-widget h1,
    #kbc-energy-widget h2{
      font-weight:800;
    }
    #kbc-energy-widget h3,
    #kbc-energy-widget h4{
      font-weight:700;
    }
    #kbc-energy-widget h2{
      margin:0 0 1rem;
      color:var(--night);
      font-size:clamp(1.7rem,3vw,2.6rem);
      line-height:1.12;
      letter-spacing:-.035em;
    }
    #kbc-energy-widget p,
    #kbc-energy-widget li,
    #kbc-energy-widget blockquote{
      line-height:1.65;
    }
    #kbc-energy-widget .section-intro{
      color:var(--ink-soft);
      font-size:clamp(.94rem,1.2vw,1rem);
      line-height:1.7;
    }
    #kbc-energy-widget section{
      padding:72px 0;
    }
    #kbc-energy-widget .section-head{
      max-width:820px;
      margin-bottom:2rem;
    }
    #kbc-energy-widget .section-head.center{
      margin-bottom:2.5rem;
    }
    #kbc-energy-widget .kicker{
      gap:.55rem;
      margin-bottom:.75rem;
      color:var(--purple-2);
      font-size:.72rem;
      font-weight:800;
      letter-spacing:.12em;
    }
    #kbc-energy-widget .kicker::before{
      width:24px;
      height:3px;
      background:var(--gold);
    }
    #kbc-energy-widget .btn{
      min-width:190px;
      min-height:48px;
      padding:.78rem 1.15rem;
      border-radius:11px;
      font-size:.875rem;
      font-weight:700;
      box-shadow:none;
      transition:background-color .2s ease,border-color .2s ease,color .2s ease,box-shadow .2s ease,transform .2s ease;
    }
    #kbc-energy-widget .btn:hover,
    #kbc-energy-widget .btn:focus-visible{
      transform:translateY(-1px);
      box-shadow:0 8px 18px rgba(32,20,50,.12);
    }
    #kbc-energy-widget .btn-primary{
      border-color:var(--gold);
      background:var(--gold);
      color:#2d230d;
    }
    #kbc-energy-widget .btn-primary:hover{
      background:#d9ae45;
      border-color:#d9ae45;
    }
    #kbc-energy-widget .btn-dark{
      border-color:rgba(92,37,156,.2);
      background:var(--purple-2);
      color:#ffffff;
    }
    #kbc-energy-widget .btn-dark:hover{
      background:var(--medium-purple,#3d285d);
    }
    #kbc-energy-widget .btn-ghost{
      border-color:rgba(255,255,255,.28);
      background:rgba(255,255,255,.08);
      color:#ffffff;
    }
    #kbc-energy-widget :is(a,button,summary):focus-visible{
      outline:3px solid var(--gold);
      outline-offset:3px;
    }

    /* Hero */
    #kbc-energy-widget .hero{
      padding:72px 0 0;
      background:
        radial-gradient(circle at 12% 14%,rgba(117,64,220,.16),transparent 30%),
        radial-gradient(circle at 88% 18%,rgba(229,189,89,.09),transparent 25%),
        linear-gradient(135deg,#1b102d,#302048,#201432);
    }
    #kbc-energy-widget .hero::before{
      opacity:.42;
    }
    #kbc-energy-widget .hero::after{
      background:radial-gradient(circle,rgba(117,64,220,.09),transparent 68%);
    }
    #kbc-energy-widget .hero-grid{
      grid-template-columns:minmax(0,1.05fr) minmax(360px,.95fr);
      gap:clamp(2rem,4vw,4rem);
      align-items:center;
    }
    #kbc-energy-widget .hero-eyebrow{
      margin-bottom:1.05rem;
      padding:.45rem .72rem;
      border-radius:999px;
      border-color:rgba(255,255,255,.2);
      background:rgba(255,255,255,.065);
      color:var(--gold);
    }
    #kbc-energy-widget .hero h1{
      max-width:760px;
      margin:0 0 1.15rem;
      font-size:clamp(2.5rem,5vw,4.4rem)!important;
      line-height:1;
      letter-spacing:-.05em;
    }
    #kbc-energy-widget .hero-lead{
      max-width:700px;
      margin-bottom:1.35rem;
      color:#ece7f2;
      font-size:clamp(1rem,1.5vw,1.14rem);
      line-height:1.65;
    }
    #kbc-energy-widget .hero-proof{
      gap:.5rem;
      margin-bottom:1.5rem;
    }
    #kbc-energy-widget .hero-proof span{
      padding:.42rem .68rem;
      border-radius:999px;
      background:rgba(255,255,255,.065);
      font-size:.78rem;
    }
    #kbc-energy-widget .hero-actions{
      gap:.75rem;
    }
    #kbc-energy-widget .hero-image-card{
      width:min(100%,520px);
      padding:8px;
      border-radius:22px;
      border-color:rgba(255,255,255,.18);
      background:rgba(255,255,255,.075);
      box-shadow:0 18px 48px rgba(10,5,18,.26);
    }
    #kbc-energy-widget .hero-image-stage{
      border-radius:16px;
      aspect-ratio:16/10;
    }
    #kbc-energy-widget .hero-image-stage>img{
      object-fit:cover;
      object-position:center;
    }
    #kbc-energy-widget .hero-image-card:hover .hero-image-stage>img{
      transform:scale(1.015);
    }
    #kbc-energy-widget .hero-image-badge{
      top:20px;
      left:20px;
    }
    #kbc-energy-widget .hero-image-caption{
      right:20px;
      bottom:20px;
      left:20px;
    }
    #kbc-energy-widget .hero-image-caption strong{
      font-size:1.1rem;
      font-weight:800;
    }
    #kbc-energy-widget .hero-statbar{
      margin-top:48px;
    }
    #kbc-energy-widget .hero-stat{
      min-height:106px;
      padding:1.15rem 1.2rem 1.3rem;
    }
    #kbc-energy-widget .hero-stat b{
      font-size:.98rem;
      font-weight:800;
    }
    #kbc-energy-widget .hero-stat span{
      font-size:14px;
      line-height:1.5;
    }

    /* Capability rail */
    #kbc-energy-widget .capability-rail{
      padding:18px 0;
      background:#ffffff;
    }
    #kbc-energy-widget .rail-window{
      padding:10px 0;
      border:1px solid rgba(87,58,125,.13);
      border-radius:16px;
      background:#ffffff;
      box-shadow:0 8px 24px rgba(32,20,50,.055);
    }
    #kbc-energy-widget .rail-group{
      gap:1rem;
      padding-right:1rem;
    }
    #kbc-energy-widget .rail-item{
      min-height:46px;
      padding:5px 14px 5px 6px;
      border:1px solid rgba(87,58,125,.1);
      border-radius:12px;
      background:#ffffff;
      color:var(--ink);
      font-size:.78rem;
    }
    #kbc-energy-widget .rail-logo{
      width:76px;
      height:38px;
      flex:0 0 76px;
      display:block;
      object-fit:contain;
      object-position:center;
      padding:3px;
      border:1px solid rgba(87,58,125,.1);
      border-radius:9px;
      background-color:#ffffff;
      box-shadow:inset 0 0 0 1px rgba(255,255,255,.7);
    }

    /* Alternating section rhythm */
    #kbc-energy-widget .challenge{background:#ffffff;}
    #kbc-energy-widget .sector-section{background:#f7f5fa;color:var(--ink);}
    #kbc-energy-widget .pathways{background:#ffffff;}
    #kbc-energy-widget .outputs{background:#f7f5fa;}
    #kbc-energy-widget .career-section{background:#ffffff;}
    #kbc-energy-widget .delivery{background:#f7f5fa;}
    #kbc-energy-widget .employer{background:#f7f5fa;}
    #kbc-energy-widget .guide{background:#ffffff;}
    #kbc-energy-widget .faq{background:#f7f5fa;}
    #kbc-energy-widget .final-cta{background:#ffffff;color:var(--ink);}

    /* Shared card language */
    #kbc-energy-widget :is(.challenge-card,.path-card,.output-card,.career-card,.delivery-step,.impact-main,.impact-card,.sector-copy,.sector-grid,details){
      border:1px solid var(--line);
      border-radius:17px;
      background:#ffffff;
      box-shadow:var(--shadow-sm);
    }
    #kbc-energy-widget :is(.challenge-card,.path-card,.output-card,.career-card,.delivery-step){
      height:100%;
      padding:22px;
    }

    /* Challenge */
    #kbc-energy-widget .challenge-bento{
      grid-template-columns:minmax(0,1fr) minmax(0,1fr);
      gap:1rem;
      align-items:stretch;
    }
    #kbc-energy-widget .challenge-main{
      min-height:390px;
      padding:28px;
      border-radius:18px;
      box-shadow:var(--shadow-sm);
    }
    #kbc-energy-widget .challenge-main h3{
      font-size:clamp(1.7rem,3vw,2.6rem);
      line-height:1.12;
    }
    #kbc-energy-widget .challenge-main p{
      color:#ebe5f1;
      font-size:.95rem;
    }
    #kbc-energy-widget .challenge-quote{
      right:28px;
      bottom:28px;
      left:28px;
      color:var(--gold);
      font-size:.95rem;
    }
    #kbc-energy-widget .challenge-side{
      grid-template-columns:repeat(2,minmax(0,1fr));
      grid-auto-rows:1fr;
      gap:1rem;
    }
    #kbc-energy-widget .challenge-card{
      display:flex;
      flex-direction:column;
    }
    #kbc-energy-widget .challenge-card .number{
      width:38px;
      height:38px;
      margin-bottom:.85rem;
      border-radius:11px;
      background:var(--lav);
      color:var(--purple-2);
    }
    #kbc-energy-widget .challenge-card h3{
      color:var(--night);
      font-size:1rem;
    }
    #kbc-energy-widget .challenge-card p{
      color:var(--ink-soft);
      font-size:14px;
    }

    /* Sector tabs and panels */
    #kbc-energy-widget .sector-section::before{
      display:none;
    }
    #kbc-energy-widget .sector-section h2,
    #kbc-energy-widget .sector-section h3{
      color:var(--night)!important;
      -webkit-text-fill-color:var(--night);
    }
    #kbc-energy-widget .sector-section .section-intro{
      color:var(--ink-soft);
    }
    #kbc-energy-widget .sector-tabs{
      gap:.65rem;
      margin-bottom:1rem;
    }
    #kbc-energy-widget .sector-tab{
      min-height:44px;
      padding:.68rem .95rem;
      border:1px solid rgba(87,58,125,.18);
      border-radius:11px;
      background:#ffffff;
      color:var(--purple-2);
      font-size:14px;
      transition:background-color .2s ease,border-color .2s ease,color .2s ease;
    }
    #kbc-energy-widget .sector-tab:hover{
      background:var(--lav);
    }
    #kbc-energy-widget .sector-tab.active{
      border-color:rgba(92,37,156,.16);
      background:var(--lav);
      color:var(--purple-2);
    }
    #kbc-energy-widget .sector-display{
      grid-template-columns:.9fr 1.1fr;
      gap:1rem;
      align-items:stretch;
    }
    #kbc-energy-widget .sector-copy,
    #kbc-energy-widget .sector-grid{
      border-radius:17px;
      background:#ffffff;
      backdrop-filter:none;
    }
    #kbc-energy-widget .sector-copy{
      min-height:330px;
      padding:24px;
    }
    #kbc-energy-widget .sector-copy h3{
      font-size:clamp(1.45rem,2.4vw,2rem);
    }
    #kbc-energy-widget .sector-copy p{
      color:var(--ink-soft);
      font-size:.93rem;
    }
    #kbc-energy-widget .sector-cta{
      color:var(--purple-2);
    }
    #kbc-energy-widget .sector-grid{
      padding:14px;
      grid-template-columns:repeat(2,minmax(0,1fr));
      grid-auto-rows:1fr;
    }
    #kbc-energy-widget .sector-outcome{
      height:100%;
      padding:18px;
      border:1px solid var(--line);
      border-radius:14px;
      background:#f7f5fa;
    }
    #kbc-energy-widget .sector-outcome strong{
      color:var(--purple-2);
      font-size:.88rem;
    }
    #kbc-energy-widget .sector-outcome span{
      color:var(--ink-soft);
      font-size:14px;
    }
    #kbc-energy-widget .sector-photo-grid{
      grid-template-columns:repeat(3,minmax(0,1fr));
      gap:1rem;
    }
    #kbc-energy-widget .sector-photo-card{
      min-height:270px;
      border:0;
      border-radius:18px;
      box-shadow:var(--shadow-sm);
    }
    #kbc-energy-widget .sector-photo-card img{
      min-height:270px;
      object-fit:cover;
      object-position:center;
    }
    #kbc-energy-widget .sector-photo-card:hover img{
      transform:scale(1.015);
    }

    /* Pathways, outputs and careers */
    #kbc-energy-widget .path-grid{
      grid-template-columns:repeat(4,minmax(0,1fr));
      gap:1rem;
      align-items:stretch;
    }
    #kbc-energy-widget .path-card:nth-child(n){
      grid-column:auto;
      min-height:330px;
    }
    #kbc-energy-widget .path-card::before{
      height:4px;
      background:var(--purple-2);
    }
    #kbc-energy-widget .path-card.dark{
      border-color:rgba(255,255,255,.1);
      background:var(--night-2);
      color:#ffffff;
    }
    #kbc-energy-widget .path-index{
      margin-bottom:1.15rem;
    }
    #kbc-energy-widget .path-icon{
      width:42px;
      height:42px;
      border-radius:12px;
      background:var(--lav);
      color:var(--purple-2);
    }
    #kbc-energy-widget .path-card h3{
      color:var(--night);
      font-size:1.05rem;
      line-height:1.35;
    }
    #kbc-energy-widget .path-card p{
      color:var(--ink-soft);
      font-size:14px;
    }
    #kbc-energy-widget .path-list{
      gap:.56rem;
      padding:0;
      margin:auto 0 0;
    }
    #kbc-energy-widget .path-list li{
      position:relative;
      padding-left:1.35rem;
      color:#4e5665;
      font-size:14px;
      line-height:1.55;
    }
    #kbc-energy-widget .path-list li::before{
      top:.36em;
      width:14px;
      height:14px;
      border:2px solid rgba(92,37,156,.22);
      background:var(--purple-2);
      box-shadow:inset 0 0 0 3px #ffffff;
    }
    #kbc-energy-widget .dark .path-list li::before{
      border-color:rgba(255,255,255,.28);
      box-shadow:inset 0 0 0 3px var(--night-2);
    }
    /* Keep every line in the first dark pathway card clearly visible in Elementor. */
    #kbc-energy-widget .path-card.dark p{
      color:#ffffff!important;
      -webkit-text-fill-color:#ffffff!important;
      opacity:1!important;
    }
    #kbc-energy-widget .path-card.dark .path-list li{
      color:#ffffff!important;
      -webkit-text-fill-color:#ffffff!important;
      opacity:1!important;
    }
    #kbc-energy-widget .path-card.dark .path-list li::before{
      border-color:rgba(229,189,89,.5);
      background:var(--gold);
      box-shadow:inset 0 0 0 3px var(--night-2);
    }
    #kbc-energy-widget .output-grid,
    #kbc-energy-widget .career-map{
      align-items:stretch;
    }
    #kbc-energy-widget .output-card,
    #kbc-energy-widget .career-card{
      display:flex;
      flex-direction:column;
    }
    #kbc-energy-widget .output-icon{
      width:43px;
      height:43px;
      margin-bottom:.9rem;
      border-radius:12px;
      background:var(--lav);
      color:var(--purple-2);
    }
    #kbc-energy-widget .output-card h3,
    #kbc-energy-widget .career-card h3{
      color:var(--night);
      font-size:1rem;
    }
    #kbc-energy-widget .output-card p,
    #kbc-energy-widget .career-card p{
      color:var(--ink-soft);
      font-size:14px;
    }
    #kbc-energy-widget .career-card{
      background:#ffffff;
    }
    #kbc-energy-widget .career-code{
      border-radius:12px;
      background:var(--purple-2);
    }
    #kbc-energy-widget .career-level{
      border-radius:999px;
      background:var(--lav);
      color:var(--purple-2);
    }
    #kbc-energy-widget .career-arrow{
      margin-top:auto;
      padding-top:1.15rem;
      color:var(--purple-2);
    }

    /* Delivery */
    #kbc-energy-widget .delivery-visual{
      margin-bottom:1rem;
      border-radius:18px;
      box-shadow:var(--shadow-sm);
    }
    #kbc-energy-widget .delivery-visual img{
      min-height:310px;
      object-fit:cover;
      object-position:center;
    }
    #kbc-energy-widget .delivery-visual figcaption{
      padding:clamp(1.5rem,4vw,2.5rem);
    }
    #kbc-energy-widget .delivery-visual h3{
      color:var(--night);
      font-size:clamp(1.45rem,2.5vw,2.1rem);
    }
    #kbc-energy-widget .delivery-steps{
      align-items:stretch;
    }
    #kbc-energy-widget .delivery-step{
      display:flex;
      flex-direction:column;
    }
    #kbc-energy-widget .delivery-step:not(:last-child)::after{
      background:var(--purple-2);
    }
    #kbc-energy-widget .delivery-step h3{
      color:var(--night);
    }
    #kbc-energy-widget .delivery-step p{
      color:var(--ink-soft);
      font-size:14px;
    }

    /* Employer, guide, FAQ and final CTA */
    #kbc-energy-widget .impact-grid{
      align-items:stretch;
    }
    #kbc-energy-widget .impact-main{
      padding:24px;
      background:#ffffff;
    }
    #kbc-energy-widget .impact-main h3{
      color:var(--night);
      font-size:1.4rem;
    }
    #kbc-energy-widget .impact-measures{
      align-items:stretch;
    }
    #kbc-energy-widget .impact-measure{
      height:100%;
      padding:16px;
      border:1px solid var(--line);
      border-left:4px solid var(--purple-2);
      border-radius:14px;
      background:#ffffff;
    }
    #kbc-energy-widget .impact-measure b{
      color:var(--purple-2);
    }
    #kbc-energy-widget .impact-measure span{
      color:var(--ink-soft);
      font-size:14px;
    }
    #kbc-energy-widget .impact-side{
      grid-template-rows:repeat(2,minmax(0,1fr));
    }
    #kbc-energy-widget .impact-card,
    #kbc-energy-widget .impact-card.gold{
      display:flex;
      flex-direction:column;
      justify-content:center;
      padding:22px;
      border-left:4px solid var(--purple-2);
      background:#ffffff;
      color:var(--ink);
    }
    #kbc-energy-widget .impact-card h3,
    #kbc-energy-widget .impact-card:not(.gold) h3{
      color:var(--night)!important;
      -webkit-text-fill-color:var(--night);
    }
    #kbc-energy-widget .impact-card p,
    #kbc-energy-widget .impact-card.gold p{
      color:var(--ink-soft);
      font-size:14px;
    }
    #kbc-energy-widget .guide-grid{
      grid-template-columns:repeat(2,minmax(0,1fr));
      gap:clamp(2rem,5vw,4rem);
      align-items:center;
    }
    #kbc-energy-widget .guide-cover{
      display:block;
      width:100%;
      max-width:none;
      height:auto;
      border:0;
      border-radius:0;
      object-fit:contain;
      object-position:center;
      box-shadow:none;
    }
    #kbc-energy-widget .guide-list{
      align-items:stretch;
    }
    #kbc-energy-widget .guide-list div{
      height:100%;
      padding:14px;
      border-radius:14px;
      background:#ffffff;
      color:var(--ink);
      font-size:14px;
    }
    #kbc-energy-widget .guide-list div::before{
      margin-top:.05rem;
      background:var(--purple-2);
      color:#ffffff;
    }
    #kbc-energy-widget details{
      background:#ffffff;
    }
    #kbc-energy-widget summary{
      color:var(--night);
      font-size:.92rem;
      font-weight:700;
    }
    #kbc-energy-widget summary::after{
      border-radius:10px;
      background:var(--lav);
      color:var(--purple-2);
    }
    #kbc-energy-widget details p{
      color:var(--ink-soft);
      font-size:14px;
    }
    #kbc-energy-widget details .faq-answer{
      padding:0 0 1rem;
    }
    #kbc-energy-widget details .faq-answer ul{
      display:grid;
      gap:.6rem;
      margin:0;
      padding:0;
      list-style:none;
    }
    #kbc-energy-widget details .faq-answer li{
      position:relative;
      margin:0;
      padding-left:1.25rem;
      color:var(--ink-soft);
      font-size:14px;
      line-height:1.65;
    }
    #kbc-energy-widget details .faq-answer li::before{
      content:"";
      position:absolute;
      top:.7em;
      left:0;
      width:7px;
      height:7px;
      border-radius:50%;
      background:var(--purple-2);
    }
    #kbc-energy-widget .faq-actions{
      display:flex;
      justify-content:center;
      width:100%;
      max-width:940px;
      margin-top:2rem;
      margin-right:auto!important;
      margin-left:auto!important;
      align-self:center!important;
    }
    #kbc-energy-widget .more-faq-btn{
      display:inline-flex;
      min-width:220px;
      border:0 !important;
      background:transparent !important;
      background-image:none !important;
      color:var(--purple-2) !important;
      box-shadow:none !important;
      font-weight:800;
      margin-inline:auto;
    }
    #kbc-energy-widget .more-faq-btn:hover,
    #kbc-energy-widget .more-faq-btn:focus-visible,
    #kbc-energy-widget .more-faq-btn:active{
      border:0 !important;
      background:transparent !important;
      background-image:none !important;
      color:var(--bright-purple,#7540dc) !important;
      box-shadow:none !important;
      transform:translateY(-2px);
    }

    /* Scroll-only availability CTA — kept outside the Elementor widget shell. */
    #kbc-scroll-cta{
      --kbc-cta-gold:#d7a72a;
      position:fixed;
      z-index:9999;
      right:0;
      bottom:0;
      left:0;
      border-top:1px solid rgba(229,189,89,.34);
      background:linear-gradient(90deg,#352071 0%,#241044 45%,#160a2d 100%);
      color:#ffffff;
      box-shadow:0 -12px 35px rgba(21,8,43,.2);
      opacity:0;
      visibility:hidden;
      transform:translateY(calc(100% + 16px));
      pointer-events:none;
      box-sizing:border-box;
      font-family:Inter,Arial,Helvetica,sans-serif;
      transition:opacity .3s ease,transform .38s cubic-bezier(.22,.8,.28,1),visibility .3s ease;
    }
    #kbc-scroll-cta *{box-sizing:border-box}
    #kbc-scroll-cta.is-visible{
      opacity:1;
      visibility:visible;
      transform:translateY(0);
      pointer-events:auto;
    }
    #kbc-scroll-cta .scroll-cta-inner{
      width:min(1200px,calc(100% - 40px));
      min-height:78px;
      margin-inline:auto;
      display:grid;
      grid-template-columns:auto minmax(0,1fr) auto;
      align-items:center;
      gap:14px;
      padding:11px 0;
    }
    #kbc-scroll-cta .scroll-cta-icon{
      width:36px;
      height:36px;
      display:grid;
      place-items:center;
      border:1px solid rgba(255,255,255,.14);
      border-radius:11px;
      background:rgba(255,255,255,.08);
    }
    #kbc-scroll-cta .scroll-cta-icon::before{
      content:"";
      width:9px;
      height:9px;
      border-radius:50%;
      background:var(--kbc-cta-gold);
      box-shadow:0 0 0 5px rgba(229,189,89,.14);
    }
    #kbc-scroll-cta .scroll-cta-copy strong{
      display:block;
      margin-bottom:2px;
      color:#ffffff;
      font-size:.94rem;
      font-weight:800;
      line-height:1.25;
    }
    #kbc-scroll-cta .scroll-cta-copy span{
      display:block;
      color:#ded5e9;
      font-size:.72rem;
      font-weight:600;
      line-height:1.45;
    }
    #kbc-scroll-cta .scroll-cta-button{
      min-height:48px;
      display:inline-flex;
      align-items:center;
      justify-content:center;
      gap:.55rem;
      padding:.75rem 1.05rem;
      border:1px solid var(--kbc-cta-gold);
      border-radius:11px;
      background:var(--kbc-cta-gold);
      color:#2d230d;
      box-shadow:0 8px 20px rgba(0,0,0,.16);
      text-decoration:none;
      font-size:.78rem;
      font-weight:800;
      white-space:nowrap;
      transition:background-color .2s ease,transform .2s ease,box-shadow .2s ease;
    }
    #kbc-scroll-cta .scroll-cta-button:hover,
    #kbc-scroll-cta .scroll-cta-button:focus-visible{
      background:#f0cb70;
      transform:translateY(-1px);
      box-shadow:0 11px 24px rgba(0,0,0,.22);
    }
    #kbc-energy-widget .final-cta{
      padding:54px 0;
      border-top:1px solid var(--line);
    }
    #kbc-energy-widget .final-cta::after{
      display:none;
    }
    #kbc-energy-widget .final-cta h2{
      max-width:820px;
      color:var(--night)!important;
      -webkit-text-fill-color:var(--night);
    }
    #kbc-energy-widget .final-cta p{
      max-width:710px;
      margin-bottom:1.4rem;
      color:var(--ink-soft);
    }
    #kbc-energy-widget .final-cta .btn-ghost{
      border-color:rgba(92,37,156,.18);
      background:var(--lav);
      color:var(--purple-2);
    }

    @media(max-width:1050px){
      #kbc-energy-widget section{padding:60px 0;}
      #kbc-energy-widget .hero{padding-top:60px;}
      #kbc-energy-widget .hero-grid,
      #kbc-energy-widget .challenge-bento,
      #kbc-energy-widget .sector-display,
      #kbc-energy-widget .impact-grid,
      #kbc-energy-widget .guide-grid,
      #kbc-energy-widget .delivery-visual{
        grid-template-columns:1fr;
      }
      #kbc-energy-widget .guide-cover{
        width:min(100%,680px);
        justify-self:center;
      }
      #kbc-energy-widget .hero-image-card{
        justify-self:start;
        width:min(100%,620px);
      }
      #kbc-energy-widget .path-grid{
        grid-template-columns:repeat(2,minmax(0,1fr));
      }
      #kbc-energy-widget .path-card:nth-child(n){
        grid-column:auto;
      }
      #kbc-energy-widget .sector-photo-grid{
        grid-template-columns:repeat(2,minmax(0,1fr));
      }
      #kbc-energy-widget .sector-photo-card:first-child{
        grid-column:1/-1;
      }
      #kbc-energy-widget .delivery-visual img{
        max-height:420px;
      }
    }
    @media(max-width:768px){
      #kbc-energy-widget{
        --wrap:calc(100% - 28px);
        font-size:15px;
      }
      #kbc-energy-widget section{
        padding:50px 0;
      }
      #kbc-energy-widget .hero{
        padding-top:50px;
      }
      #kbc-energy-widget .hero h1{
        font-size:clamp(2.5rem,11vw,3.35rem)!important;
        line-height:1;
      }
      #kbc-energy-widget .hero-grid{
        gap:2rem;
      }
      #kbc-energy-widget .hero-actions .btn,
      #kbc-energy-widget .final-actions .btn,
      #kbc-energy-widget .guide .btn{
        width:100%;
      }
      #kbc-energy-widget .hero-statbar{
        grid-template-columns:1fr 1fr;
      }
      #kbc-energy-widget .challenge-side,
      #kbc-energy-widget .sector-grid,
      #kbc-energy-widget .sector-photo-grid,
      #kbc-energy-widget .path-grid,
      #kbc-energy-widget .output-grid,
      #kbc-energy-widget .career-map,
      #kbc-energy-widget .delivery-steps,
      #kbc-energy-widget .impact-measures,
      #kbc-energy-widget .guide-list{
        grid-template-columns:1fr;
      }
      #kbc-energy-widget .sector-photo-card:first-child{
        grid-column:auto;
      }
      #kbc-energy-widget .path-card:nth-child(n){
        grid-column:auto;
        min-height:auto;
      }
      #kbc-energy-widget .sector-tabs{
        flex-wrap:nowrap;
        overflow-x:auto;
        padding-bottom:.25rem;
        scrollbar-width:thin;
      }
      #kbc-energy-widget .sector-tab{
        flex:0 0 auto;
      }
      #kbc-energy-widget .final-cta{
        padding:48px 0;
      }
      #kbc-energy-widget .final-actions{
        flex-direction:column;
      }
      #kbc-scroll-cta .scroll-cta-inner{
        grid-template-columns:auto minmax(0,1fr) auto;
        gap:10px;
      }
      #kbc-scroll-cta .scroll-cta-copy span{
        display:none;
      }
      #kbc-scroll-cta .scroll-cta-button{
        min-width:0;
        padding-inline:.8rem;
        white-space:normal;
        text-align:center;
        line-height:1.25;
      }
    }
    @media(max-width:480px){
      #kbc-energy-widget .hero-statbar{
        grid-template-columns:1fr;
      }
      #kbc-energy-widget .hero-stat{
        min-height:auto;
        border-right:0;
        border-bottom:1px solid rgba(255,255,255,.12);
      }
      #kbc-energy-widget .hero-stat:last-child{
        border-bottom:0;
      }
      #kbc-energy-widget .hero-image-stage{
        aspect-ratio:4/3;
      }
      #kbc-energy-widget .challenge-main{
        min-height:450px;
        padding:22px;
      }
      #kbc-energy-widget .challenge-quote{
        right:22px;
        bottom:22px;
        left:22px;
      }
      #kbc-energy-widget :is(.challenge-card,.path-card,.output-card,.career-card,.delivery-step){
        padding:20px;
      }
      #kbc-scroll-cta .scroll-cta-inner{
        width:calc(100% - 24px);
        grid-template-columns:minmax(0,1fr) auto;
        min-height:0;
        padding:9px 0;
      }
      #kbc-scroll-cta .scroll-cta-icon{
        display:none;
      }
      #kbc-scroll-cta .scroll-cta-copy strong{
        font-size:.8rem;
      }
      #kbc-scroll-cta .scroll-cta-button{
        min-height:42px;
        max-width:158px;
        font-size:.7rem;
      }
    }
    @media(prefers-reduced-motion:reduce){
      #kbc-energy-widget *,
      #kbc-energy-widget *::before,
      #kbc-energy-widget *::after{
        scroll-behavior:auto!important;
        animation-duration:.01ms!important;
        animation-iteration-count:1!important;
        transition-duration:.01ms!important;
      }
      #kbc-energy-widget .reveal{
        opacity:1;
        transform:none;
      }
    }


    /* ================================================================
       Kent Business College website-wide design system — final layer
       This layer is intentionally scoped to the supplied widget.
       ================================================================ */
    #kbc-energy-widget{
      /* Brand colours */
      --kbc-navy:#061d28;
      --kbc-navy-secondary:#0d2d39;
      --kbc-navy-deep:#04141c;
      --kbc-teal:#0c7d78;
      --kbc-teal-light:#1aa79d;
      --kbc-gold:#d7b15a;
      --kbc-lime:#d9efaa;

      /* Text and surfaces */
      --kbc-text-primary:#12232c;
      --kbc-text-secondary:#60717a;
      --kbc-text-inverse:#ffffff;
      --kbc-text-on-gold:#172429;
      --kbc-surface-primary:#ffffff;
      --kbc-surface-warm:#f3f2ec;
      --kbc-surface-cool:#eef5f4;
      --kbc-surface-dark:#061d28;
      --kbc-border:rgba(18,35,44,.13);
      --kbc-border-dark:rgba(255,255,255,.16);

      /* Typography */
      --kbc-font-body:"DM Sans",Arial,Helvetica,sans-serif;
      --kbc-font-display:"Source Serif 4",Georgia,serif;
      --kbc-font-data:"Manrope",Arial,Helvetica,sans-serif;

      /* Geometry and motion */
      --kbc-container:min(1240px,calc(100% - 40px));
      --kbc-reading-width:720px;
      --kbc-radius-sm:10px;
      --kbc-radius-md:14px;
      --kbc-radius-lg:18px;
      --kbc-radius-xl:22px;
      --kbc-radius-2xl:26px;
      --kbc-radius-3xl:28px;
      --kbc-radius-pill:999px;
      --kbc-shadow-sm:0 10px 30px rgba(4,31,42,.08);
      --kbc-shadow-md:0 18px 50px rgba(4,31,42,.14);
      --kbc-shadow-lg:0 28px 90px rgba(4,31,42,.20);
      --kbc-transition-fast:.2s ease;
      --kbc-transition-default:.3s ease;
      --kbc-transition-reveal:.7s ease;

      /* Compatibility aliases used by the original component CSS */
      --ink:var(--kbc-text-primary);
      --ink-soft:var(--kbc-text-secondary);
      --night:var(--kbc-navy);
      --night-2:var(--kbc-navy-secondary);
      --deep-purple:var(--kbc-navy-deep);
      --medium-purple:var(--kbc-navy-secondary);
      --muted-purple:var(--kbc-teal);
      --primary-purple:var(--kbc-teal);
      --bright-purple:var(--kbc-teal-light);
      --light-purple:var(--kbc-surface-cool);
      --section-bg:var(--kbc-surface-warm);
      --soft-gold:#f4e8c7;
      --purple:var(--kbc-teal);
      --purple-2:var(--kbc-teal);
      --violet:var(--kbc-teal-light);
      --gold:var(--kbc-gold);
      --gold-2:var(--kbc-lime);
      --cream:var(--kbc-surface-warm);
      --lav:var(--kbc-surface-cool);
      --lav-2:#dcebea;
      --green:var(--kbc-teal);
      --blue:var(--kbc-navy-secondary);
      --line:var(--kbc-border);
      --white:#fff;
      --shadow:var(--kbc-shadow-md);
      --shadow-sm:var(--kbc-shadow-sm);
      --radius:var(--kbc-radius-3xl);
      --radius-sm:var(--kbc-radius-lg);
      --wrap:var(--kbc-container);

      background:var(--kbc-surface-primary);
      color:var(--kbc-text-primary);
      font-family:var(--kbc-font-body);
      font-size:16px;
      line-height:1.65;
      scroll-padding-top:24px;
    }
    #kbc-energy-widget,
    #kbc-energy-widget p,
    #kbc-energy-widget li,
    #kbc-energy-widget a,
    #kbc-energy-widget button,
    #kbc-energy-widget summary,
    #kbc-energy-widget blockquote,
    #kbc-energy-widget figcaption{
      font-family:var(--kbc-font-body)!important;
    }
    #kbc-energy-widget h1,
    #kbc-energy-widget h2,
    #kbc-energy-widget h3,
    #kbc-energy-widget h4,
    #kbc-energy-widget .quote-card blockquote{
      font-family:var(--kbc-font-display)!important;
      font-weight:600;
      text-wrap:balance;
    }
    #kbc-energy-widget :is(.hero-stat b,.path-index,.career-code,.career-level,.delivery-step small,.kicker,.hero-eyebrow,.hero-image-badge,.sector-tab,.number){
      font-family:var(--kbc-font-data)!important;
    }
    #kbc-energy-widget img{
      object-fit:cover;
    }
    #kbc-energy-widget .wrap{
      width:var(--kbc-container);
      margin-inline:auto;
    }
    #kbc-energy-widget section{
      padding:112px 0;
    }
    #kbc-energy-widget .section-head{
      max-width:var(--kbc-reading-width);
      margin-bottom:48px;
    }
    #kbc-energy-widget .section-head.center{
      max-width:820px;
      margin-bottom:48px;
    }
    #kbc-energy-widget h2{
      margin:0 0 18px;
      color:var(--kbc-navy);
      font-size:clamp(40px,5vw,62px);
      line-height:1.02;
      letter-spacing:-.035em;
    }
    #kbc-energy-widget h3{
      color:var(--kbc-navy);
      letter-spacing:-.018em;
    }
    #kbc-energy-widget .section-intro{
      max-width:var(--kbc-reading-width);
      color:var(--kbc-text-secondary);
      font-size:18px;
      line-height:1.6;
    }
    #kbc-energy-widget .kicker{
      color:var(--kbc-teal);
      font-size:10px;
      font-weight:800;
      line-height:1.3;
      letter-spacing:.17em;
    }
    #kbc-energy-widget .kicker::before{
      width:28px;
      height:2px;
      background:var(--kbc-gold);
    }
    #kbc-energy-widget :is(a,button,summary):focus-visible{
      outline:3px solid var(--kbc-gold);
      outline-offset:3px;
    }

    /* Buttons */
    #kbc-energy-widget .btn{
      min-width:0;
      min-height:44px;
      padding:13px 18px;
      border:1px solid transparent;
      border-radius:var(--kbc-radius-sm);
      font-family:var(--kbc-font-body)!important;
      font-size:13px;
      font-weight:800;
      line-height:1;
      box-shadow:none;
      transition:transform var(--kbc-transition-fast),box-shadow var(--kbc-transition-fast),background-color var(--kbc-transition-fast),border-color var(--kbc-transition-fast),color var(--kbc-transition-fast);
    }
    #kbc-energy-widget .btn:hover{
      transform:translateY(-2px);
    }
    #kbc-energy-widget .btn-primary{
      border-color:var(--kbc-gold);
      background:var(--kbc-gold);
      color:var(--kbc-text-on-gold);
      box-shadow:0 10px 30px rgba(215,177,90,.2);
    }
    #kbc-energy-widget .btn-primary:hover{
      border-color:#c7a047;
      background:#c7a047;
    }
    #kbc-energy-widget .btn-dark{
      border-color:var(--kbc-teal);
      background:var(--kbc-teal);
      color:#fff;
    }
    #kbc-energy-widget .btn-dark:hover{
      border-color:#086b67;
      background:#086b67;
    }
    #kbc-energy-widget .btn-ghost{
      border-color:rgba(255,255,255,.33);
      background:rgba(255,255,255,.04);
      color:#fff;
    }
    #kbc-energy-widget .btn-ghost:hover{
      background:rgba(255,255,255,.1);
    }

    /* Hero */
    #kbc-energy-widget .hero{
      padding:94px 0 0;
      color:#fff;
      background:
        radial-gradient(circle at 78% 23%,rgba(26,167,157,.23),transparent 27%),
        radial-gradient(circle at 12% 88%,rgba(215,177,90,.11),transparent 25%),
        linear-gradient(110deg,#041923 0%,#082a36 58%,#071e28 100%);
    }
    #kbc-energy-widget .hero::before{
      inset:0;
      width:auto;
      height:auto;
      right:0;
      top:0;
      border:0;
      border-radius:0;
      box-shadow:none;
      opacity:.13;
      background-image:linear-gradient(rgba(255,255,255,.10) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.10) 1px,transparent 1px);
      background-size:46px 46px;
      mask-image:linear-gradient(90deg,#000,transparent 88%);
    }
    #kbc-energy-widget .hero::after{
      left:auto;
      right:-260px;
      bottom:-290px;
      width:620px;
      height:620px;
      border:1px solid rgba(255,255,255,.08);
      background:transparent;
      box-shadow:0 0 0 70px rgba(255,255,255,.018),0 0 0 140px rgba(255,255,255,.012);
    }
    #kbc-energy-widget .hero-grid{
      grid-template-columns:minmax(0,1.02fr) minmax(360px,.98fr);
      gap:48px;
      align-items:center;
    }
    #kbc-energy-widget .hero-eyebrow{
      padding:8px 12px;
      border:1px solid rgba(255,255,255,.18);
      border-radius:var(--kbc-radius-pill);
      background:rgba(255,255,255,.06);
      color:var(--kbc-lime);
      font-size:10px;
      letter-spacing:.17em;
    }
    #kbc-energy-widget .hero-eyebrow::before,
    #kbc-energy-widget .hero-image-badge::before{
      background:var(--kbc-lime);
      box-shadow:0 0 0 5px rgba(217,239,170,.12);
    }
    #kbc-energy-widget .hero h1{
      max-width:800px;
      margin:0 0 24px;
      color:#fff!important;
      font-size:clamp(52px,6vw,84px)!important;
      font-weight:600;
      line-height:.96;
      letter-spacing:-.048em;
      -webkit-text-fill-color:#fff;
    }
    #kbc-energy-widget .hero-title-clarity,
    #kbc-energy-widget .hero-title-confidence{
      color:var(--kbc-lime)!important;
      -webkit-text-fill-color:var(--kbc-lime)!important;
      text-shadow:none;
    }
    #kbc-energy-widget .hero-title-control{
      color:#fff!important;
      -webkit-text-fill-color:#fff!important;
    }
    #kbc-energy-widget .hero-lead{
      max-width:680px;
      margin-bottom:24px;
      color:#d7e2e5;
      font-size:18px;
      line-height:1.6;
    }
    #kbc-energy-widget .hero-proof span{
      padding:8px 11px;
      border-color:rgba(255,255,255,.14);
      background:rgba(255,255,255,.055);
      color:#e8eff0;
      font-size:13px;
    }
    #kbc-energy-widget .hero-proof svg{
      color:var(--kbc-teal-light);
    }
    #kbc-energy-widget .hero-actions{
      gap:10px;
    }
    #kbc-energy-widget .hero-image-card{
      width:min(100%,540px);
      padding:8px;
      border:1px solid rgba(255,255,255,.16);
      border-radius:var(--kbc-radius-2xl);
      background:rgba(255,255,255,.075);
      box-shadow:var(--kbc-shadow-feature,0 40px 100px rgba(0,0,0,.4));
    }
    #kbc-energy-widget .hero-image-stage{
      border-radius:var(--kbc-radius-lg);
      background:var(--kbc-navy-deep);
    }
    #kbc-energy-widget .hero-image-card:hover .hero-image-stage>img{
      transform:scale(1.02);
    }
    #kbc-energy-widget .hero-image-stage::after{
      background:linear-gradient(transparent,rgba(4,20,28,.92));
    }
    #kbc-energy-widget .hero-image-badge{
      border-color:rgba(255,255,255,.18);
      background:rgba(4,20,28,.78);
      color:#fff;
    }
    #kbc-energy-widget .hero-image-caption span{
      color:#d7e2e5;
      font-size:13px;
    }
    #kbc-energy-widget .hero-statbar{
      margin-top:64px;
      border-top:1px solid var(--kbc-border-dark);
    }
    #kbc-energy-widget .hero-stat{
      min-height:116px;
      padding:22px 20px 26px;
      border-right-color:var(--kbc-border-dark);
    }
    #kbc-energy-widget .hero-stat b{
      color:#fff;
      font-size:16px;
      font-weight:700;
    }
    #kbc-energy-widget .hero-stat span{
      color:#bdcdd1;
      font-size:13px;
    }

    /* Capability rail */
    #kbc-energy-widget .capability-rail{
      padding:20px 0;
      background:var(--kbc-surface-primary);
    }
    #kbc-energy-widget .rail-window{
      width:var(--kbc-container);
      padding:10px;
      overflow-x:auto;
      border:1px solid var(--kbc-border);
      border-radius:var(--kbc-radius-lg);
      background:#fff;
      box-shadow:var(--kbc-shadow-sm);
      scrollbar-width:thin;
    }
    #kbc-energy-widget .rail-track{
      width:max-content;
      animation:none!important;
    }
    #kbc-energy-widget .rail-group{
      gap:12px;
      padding-right:0;
    }
    #kbc-energy-widget .rail-group[aria-hidden="true"]{
      display:none;
    }
    #kbc-energy-widget .rail-item{
      min-height:48px;
      padding:5px 14px 5px 6px;
      border:1px solid var(--kbc-border);
      border-radius:var(--kbc-radius-md);
      background:#fff;
      color:var(--kbc-text-primary);
      font-size:13px;
    }
    #kbc-energy-widget .rail-logo{
      border-color:var(--kbc-border);
      border-radius:var(--kbc-radius-sm);
    }

    /* Page surface rhythm */
    #kbc-energy-widget .challenge{background:var(--kbc-surface-primary);}
    #kbc-energy-widget .sector-section{background:var(--kbc-surface-warm);color:var(--kbc-text-primary);}
    #kbc-energy-widget .pathways{background:var(--kbc-surface-primary);}
    #kbc-energy-widget .outputs{background:var(--kbc-surface-cool);}
    #kbc-energy-widget .career-section{background:var(--kbc-surface-primary);}
    #kbc-energy-widget .delivery{background:var(--kbc-surface-warm);}
    #kbc-energy-widget .testimonials{background:var(--kbc-surface-primary);}
    #kbc-energy-widget .employer{background:var(--kbc-navy);color:#fff;}
    #kbc-energy-widget .guide{background:var(--kbc-surface-warm);}
    #kbc-energy-widget .faq{background:var(--kbc-surface-cool);}

    /* Shared cards */
    #kbc-energy-widget :is(.challenge-card,.path-card,.output-card,.career-card,.delivery-step,.impact-main,.impact-card,.sector-copy,.sector-grid,.quote-card,details){
      border:1px solid var(--kbc-border);
      border-radius:var(--kbc-radius-xl);
      background:#fff;
      box-shadow:none;
    }
    #kbc-energy-widget :is(.challenge-card,.path-card,.output-card,.career-card,.delivery-step){
      height:100%;
      padding:28px;
    }
    #kbc-energy-widget :is(.challenge-card,.path-card,.output-card,.career-card,.delivery-step,.sector-outcome,.impact-measure,.quote-card){
      transition:transform var(--kbc-transition-fast),box-shadow var(--kbc-transition-fast),border-color var(--kbc-transition-fast);
    }
    #kbc-energy-widget :is(.challenge-card,.path-card,.output-card,.career-card,.delivery-step,.sector-outcome,.impact-measure,.quote-card):hover{
      transform:translateY(-3px);
      border-color:rgba(12,125,120,.24);
      box-shadow:var(--kbc-shadow-sm);
    }

    /* Challenge */
    #kbc-energy-widget .challenge-bento{
      grid-template-columns:1.05fr .95fr;
      gap:20px;
    }
    #kbc-energy-widget .challenge-main{
      min-height:430px;
      padding:38px;
      border-radius:var(--kbc-radius-2xl);
      background-color:var(--kbc-navy);
      background-blend-mode:multiply;
      box-shadow:var(--kbc-shadow-md);
    }
    #kbc-energy-widget .challenge-main .kicker{
      color:var(--kbc-lime);
    }
    #kbc-energy-widget .challenge-main h3{
      max-width:12ch;
      color:#fff!important;
      font-size:clamp(32px,4vw,46px);
      line-height:1.05;
      -webkit-text-fill-color:#fff;
    }
    #kbc-energy-widget .challenge-main p{
      max-width:58ch;
      color:#d7e2e5;
      font-size:16px;
    }
    #kbc-energy-widget .challenge-quote{
      right:38px;
      bottom:38px;
      left:38px;
      border-left-color:var(--kbc-gold);
      color:var(--kbc-lime);
      font-family:var(--kbc-font-display)!important;
      font-size:18px;
    }
    #kbc-energy-widget .challenge-side{
      gap:12px;
    }
    #kbc-energy-widget .challenge-card .number{
      width:42px;
      height:42px;
      border-radius:var(--kbc-radius-md);
      background:var(--kbc-surface-cool);
      color:var(--kbc-teal);
    }
    #kbc-energy-widget .challenge-card h3{
      font-size:22px;
      line-height:1.12;
    }
    #kbc-energy-widget .challenge-card p{
      color:var(--kbc-text-secondary);
      font-size:13px;
    }

    /* Sector tabs and panels */
    #kbc-energy-widget .sector-section::before{display:none;}
    #kbc-energy-widget .sector-section h2,
    #kbc-energy-widget .sector-section h3{
      color:var(--kbc-navy)!important;
      -webkit-text-fill-color:var(--kbc-navy);
    }
    #kbc-energy-widget .sector-tabs{
      gap:8px;
      margin-bottom:18px;
    }
    #kbc-energy-widget .sector-tab{
      min-height:44px;
      padding:10px 14px;
      border:1px solid var(--kbc-border);
      border-radius:var(--kbc-radius-pill);
      background:#fff;
      color:var(--kbc-text-secondary);
      font-size:12px;
      font-weight:800;
    }
    #kbc-energy-widget .sector-tab:hover{
      border-color:rgba(12,125,120,.28);
      background:var(--kbc-surface-cool);
      color:var(--kbc-teal);
    }
    #kbc-energy-widget .sector-tab.active{
      border-color:var(--kbc-teal);
      background:var(--kbc-teal);
      color:#fff;
    }
    #kbc-energy-widget .sector-display{
      grid-template-columns:.9fr 1.1fr;
      gap:18px;
    }
    #kbc-energy-widget .sector-copy,
    #kbc-energy-widget .sector-grid{
      border-radius:var(--kbc-radius-2xl);
      background:#fff;
    }
    #kbc-energy-widget .sector-copy{
      min-height:350px;
      padding:32px;
    }
    #kbc-energy-widget .sector-copy h3{
      font-size:clamp(32px,4vw,46px);
      line-height:1.05;
    }
    #kbc-energy-widget .sector-copy p{
      color:var(--kbc-text-secondary);
      font-size:16px;
    }
    #kbc-energy-widget .sector-cta{
      color:var(--kbc-teal);
    }
    #kbc-energy-widget .sector-grid{
      padding:16px;
      gap:12px;
    }
    #kbc-energy-widget .sector-outcome{
      padding:20px;
      border:0;
      border-radius:var(--kbc-radius-lg);
      background:var(--kbc-surface-cool);
    }
    #kbc-energy-widget .sector-outcome strong{
      color:var(--kbc-teal);
      font-size:13px;
    }
    #kbc-energy-widget .sector-outcome span{
      color:var(--kbc-text-secondary);
      font-size:13px;
    }
    #kbc-energy-widget .sector-photo-card{
      border-radius:var(--kbc-radius-xl);
      box-shadow:var(--kbc-shadow-sm);
    }
    #kbc-energy-widget .sector-photo-card:hover img{
      transform:scale(1.02);
    }

    /* Pathways, outputs and careers */
    #kbc-energy-widget .path-grid{
      gap:12px;
    }
    #kbc-energy-widget .path-card{
      min-height:360px;
    }
    #kbc-energy-widget .path-card::before{
      height:3px;
      background:var(--kbc-teal);
    }
    #kbc-energy-widget .path-card.dark{
      border-color:var(--kbc-border-dark);
      background:var(--kbc-navy);
      color:#fff;
      box-shadow:var(--kbc-shadow-md);
    }
    #kbc-energy-widget .path-card.dark h3,
    #kbc-energy-widget .path-card.dark p,
    #kbc-energy-widget .path-card.dark .path-list li{
      color:#fff!important;
      -webkit-text-fill-color:#fff!important;
    }
    #kbc-energy-widget .path-icon,
    #kbc-energy-widget .output-icon{
      width:46px;
      height:46px;
      border-radius:var(--kbc-radius-md);
      background:var(--kbc-surface-cool);
      color:var(--kbc-teal);
    }
    #kbc-energy-widget .path-card h3,
    #kbc-energy-widget .output-card h3,
    #kbc-energy-widget .career-card h3{
      color:var(--kbc-navy);
      font-size:22px;
      line-height:1.12;
    }
    #kbc-energy-widget .path-card p,
    #kbc-energy-widget .output-card p,
    #kbc-energy-widget .career-card p{
      color:var(--kbc-text-secondary);
      font-size:13px;
    }
    #kbc-energy-widget .path-list li{
      color:var(--kbc-text-secondary);
      font-size:13px;
    }
    #kbc-energy-widget .path-list li::before{
      border-color:rgba(12,125,120,.22);
      background:var(--kbc-teal);
      box-shadow:inset 0 0 0 3px #fff;
    }
    #kbc-energy-widget .dark .path-list li::before{
      border-color:rgba(217,239,170,.45);
      background:var(--kbc-lime);
      box-shadow:inset 0 0 0 3px var(--kbc-navy);
    }
    #kbc-energy-widget .career-code{
      border-radius:var(--kbc-radius-sm);
      background:var(--kbc-navy);
    }
    #kbc-energy-widget .career-level{
      background:var(--kbc-surface-cool);
      color:var(--kbc-teal);
    }
    #kbc-energy-widget .career-arrow{
      color:var(--kbc-teal);
    }

    /* Delivery */
    #kbc-energy-widget .delivery-visual{
      margin-bottom:20px;
      border:0;
      border-radius:var(--kbc-radius-2xl);
      box-shadow:var(--kbc-shadow-md);
    }
    #kbc-energy-widget .delivery-visual figcaption{
      background:#fff;
    }
    #kbc-energy-widget .delivery-visual h3{
      color:var(--kbc-navy);
      font-size:clamp(32px,4vw,46px);
      line-height:1.05;
    }
    #kbc-energy-widget .delivery-step:not(:last-child)::after{
      height:1px;
      background:var(--kbc-teal);
    }
    #kbc-energy-widget .delivery-step small{
      color:var(--kbc-teal);
    }
    #kbc-energy-widget .delivery-step p{
      color:var(--kbc-text-secondary);
      font-size:13px;
    }

    /* Testimonials */
    #kbc-energy-widget .testimonial-note{
      color:var(--kbc-text-secondary);
      font-size:13px;
    }
    #kbc-energy-widget .testimonial-track{
      transition:transform var(--kbc-transition-default);
    }
    #kbc-energy-widget .quote-card{
