    #kbc-scroll-cta .scroll-cta-button{
      border-color:var(--kbc-cta-gold);
      border-radius:10px;
      background:var(--kbc-cta-gold);
      color:#172429;
    }
    #kbc-scroll-cta .scroll-cta-button:hover{
      background:#c7a047;
    }
    #kbc-scroll-cta :is(a,button):focus-visible{
      outline:3px solid #d7b15a;
      outline-offset:3px;
    }

    @media(max-width:1080px){
