    }
    @media(max-width:760px){
      #kbc-energy-widget{
        --kbc-container:min(1240px,calc(100% - 28px));
        --wrap:var(--kbc-container);
        font-size:15px;
      }
      #kbc-energy-widget section{padding:72px 0;}
      #kbc-energy-widget .hero{padding-top:64px;}
      #kbc-energy-widget h2{font-size:clamp(36px,10vw,42px);}
      #kbc-energy-widget .hero h1{font-size:clamp(44px,12vw,52px)!important;}
      #kbc-energy-widget .hero-grid{gap:36px;}
      #kbc-energy-widget .hero-actions .btn,
      #kbc-energy-widget .final-actions .btn,
      #kbc-energy-widget .guide .btn{width:100%;}
      #kbc-energy-widget .challenge-side,
      #kbc-energy-widget .sector-grid,
      #kbc-energy-widget .sector-photo-grid,
      #kbc-energy-widget .path-grid,
      #kbc-energy-widget .output-grid,
      #kbc-energy-widget .career-map,
      #kbc-energy-widget .delivery-steps,
      #kbc-energy-widget .impact-measures,
      #kbc-energy-widget .guide-list{
        grid-template-columns:1fr;
      }
      #kbc-energy-widget .sector-photo-card:first-child{grid-column:auto;}
      #kbc-energy-widget .path-card:nth-child(n){grid-column:auto;min-height:auto;}
      #kbc-energy-widget .sector-tabs{
        flex-wrap:nowrap;
        overflow-x:auto;
        padding-bottom:6px;
