        border-bottom:1px solid var(--kbc-border-dark);
      }
      #kbc-energy-widget .hero-stat:last-child{border-bottom:0;}
      #kbc-energy-widget .challenge-main{
        min-height:500px;
        padding:24px;
      }
      #kbc-energy-widget .challenge-quote{
        right:24px;
        bottom:24px;
        left:24px;
      }
      #kbc-energy-widget :is(.challenge-card,.path-card,.output-card,.career-card,.delivery-step){padding:22px;}
