    @media(prefers-reduced-motion:reduce){
      #kbc-energy-widget *,
      #kbc-energy-widget *::before,
      #kbc-energy-widget *::after{
        scroll-behavior:auto!important;
        animation-duration:.01ms!important;
        animation-iteration-count:1!important;
        transition-duration:.01ms!important;
      }
      #kbc-energy-widget .rail-track{animation:none!important;}
      #kbc-energy-widget .reveal{opacity:1;transform:none;}
    }

(function(){
    const root=document.getElementById('kbc-energy-widget');
    if(!root || root.dataset.kbcInitialised==='true') return;
    root.dataset.kbcInitialised='true';

    const sectorData={
      central:{title:'Project support',text:'The right route depends on the role, prior learning, level of responsibility and the new capability the employee needs to develop.',items:[['Project Support Officer','Coordinates actions, documents, reporting and delivery support.'],['Project Coordinator','Supports plans, stakeholders, risks and workstream activity.'],['Junior PMO Analyst','Maintains governance information, reporting and standards.'],['Associate Project Manager Level 4','Build structured project-delivery capability.']]},
      nhs:{title:'Specialist controls',text:'Project Controls Professional Level 6 is designed for employees whose role requires substantial new learning across integrated schedule, cost, risk, change and performance control.',items:[['Project Planner or Scheduler','Develops and controls integrated schedules and milestones.'],['Cost, Risk or Controls Professional','Manages baselines, forecasts, variances and decision support.'],['Programme Controller or PMO Controls Analyst','Integrates performance insight across projects and portfolios.'],['Project Controls Professional Level 6','Integrated schedule, cost, risk, change and performance control.']]},
      local:{title:'Funded apprenticeship routes',text:'Kent Business College reviews each employee’s role and prior learning before confirming the appropriate programme and funding position.',items:[['Associate Project Manager','For employees coordinating projects, managing workstreams, supporting governance and developing professional project-management capability.'],['Project Controls Professional','For planners, cost professionals, risk specialists, controls engineers and PMO teams responsible for integrated delivery performance.'],['Delivery model','Live online and workplace applied.'],['Limited funded places','Subject to availability and written confirmation.']]}
    };
    const sectorTabs=[...root.querySelectorAll('.sector-tab')];
    const sectorTitle=root.querySelector('#sectorTitle');
    const sectorText=root.querySelector('#sectorText');
    const sectorGrid=root.querySelector('#sectorGrid');
    sectorTabs.forEach(tab=>tab.addEventListener('click',()=>{
      sectorTabs.forEach(t=>{t.classList.remove('active');t.setAttribute('aria-selected','false')});
      tab.classList.add('active');tab.setAttribute('aria-selected','true');
      const data=sectorData[tab.dataset.sector];
      sectorTitle.textContent=data.title;sectorText.textContent=data.text;
      sectorGrid.innerHTML=data.items.map(i=>`<div class="sector-outcome"><strong>${i[0]}</strong><span>${i[1]}</span></div>`).join('');
    }));

    if('IntersectionObserver' in window){
      const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('in');revealObserver.unobserve(entry.target)}}),{threshold:.12});
      root.querySelectorAll('.reveal').forEach(el=>revealObserver.observe(el));
    }else{
      root.querySelectorAll('.reveal').forEach(el=>el.classList.add('in'));
    }

    root.querySelectorAll('a[href^="#"]').forEach(link=>link.addEventListener('click',event=>{
      const target=root.querySelector(link.getAttribute('href'));
      if(!target) return;
      event.preventDefault();
      target.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});
    }));

    const testimonialTrack=root.querySelector('#testimonialTrack');
    const testimonialViewport=root.querySelector('#testimonialViewport');
    const testimonialDots=root.querySelector('#testimonialDots');
    if(testimonialTrack && testimonialViewport && testimonialDots){
      const testimonialItems=[...testimonialTrack.children];
      const testimonialPrev=root.querySelector('#testimonialPrev');
      const testimonialNext=root.querySelector('#testimonialNext');
      const testimonialMobile=window.matchMedia('(max-width: 700px)');
      let testimonialPage=0;
      let testimonialTimer;
      let touchStartX=0;

      const testimonialPerPage=()=>testimonialMobile.matches?1:2;
      const testimonialPageCount=()=>Math.ceil(testimonialItems.length/testimonialPerPage());
      function showTestimonials(page){
        const count=testimonialPageCount();
        testimonialPage=(page+count)%count;
        testimonialTrack.style.transform=`translateX(-${testimonialPage*100}%)`;
        [...testimonialDots.children].forEach((dot,index)=>dot.classList.toggle('active',index===testimonialPage));
      }
      function buildTestimonialDots(){
        const count=testimonialPageCount();
        testimonialPage=Math.min(testimonialPage,count-1);
        testimonialDots.replaceChildren();
        for(let index=0;index<count;index+=1){
          const dot=document.createElement('button');
          dot.className='dot'+(index===testimonialPage?' active':'');
          dot.type='button';
          dot.setAttribute('aria-label',`Show testimonial page ${index+1}`);
          dot.addEventListener('click',()=>{showTestimonials(index);restartTestimonials()});
          testimonialDots.appendChild(dot);
        }
        showTestimonials(testimonialPage);
      }
      function restartTestimonials(){
        clearInterval(testimonialTimer);
        if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches){
          testimonialTimer=setInterval(()=>showTestimonials(testimonialPage+1),6500);
        }
      }
      testimonialPrev?.addEventListener('click',()=>{showTestimonials(testimonialPage-1);restartTestimonials()});
      testimonialNext?.addEventListener('click',()=>{showTestimonials(testimonialPage+1);restartTestimonials()});
      testimonialViewport.addEventListener('touchstart',event=>{touchStartX=event.changedTouches[0].clientX},{passive:true});
      testimonialViewport.addEventListener('touchend',event=>{
        const distance=event.changedTouches[0].clientX-touchStartX;
        if(Math.abs(distance)<45) return;
        showTestimonials(testimonialPage+(distance<0?1:-1));
        restartTestimonials();
      },{passive:true});
      testimonialMobile.addEventListener?.('change',()=>{buildTestimonialDots();restartTestimonials()});
      buildTestimonialDots();
      restartTestimonials();
    }

    const scrollCta=document.getElementById('kbc-scroll-cta');
    const scrollCtaLink=scrollCta?.querySelector('a');
    if(scrollCta && scrollCtaLink){
      scrollCtaLink.addEventListener('click',event=>{
        const target=root.querySelector(scrollCtaLink.getAttribute('href'));
        if(!target) return;
        event.preventDefault();
        target.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});
      });
      const updateScrollCta=()=>{
        const shouldShow=(window.scrollY || document.documentElement.scrollTop || 0)>180;
        scrollCta.classList.toggle('is-visible',shouldShow);
        scrollCta.setAttribute('aria-hidden',String(!shouldShow));
        scrollCtaLink.tabIndex=shouldShow?0:-1;
      };
      updateScrollCta();
      window.addEventListener('scroll',updateScrollCta,{passive:true});
      document.addEventListener('scroll',updateScrollCta,{passive:true});
    }
  })();
